package org.firstinspires.ftc.teamcode.autos;

import com.bylazar.configurables.annotations.Configurable;
import com.pedropathing.api.PoseFactory;
import com.pedropathing.math.Pose;

import org.firstinspires.ftc.teamcode.utils.Alliance;

import java.util.function.Supplier;

/**
 * Shared field points in inches and degrees. Tune the Red entries in Panels; Blue poses
 * are generated by rotating the current Red values 180 degrees about the field centre.
 * Autos read the points during INIT; re-INIT after editing. Copy tuned values back here
 * to retain them across robot restarts. Control point headings are unused.
 */
public final class Points {
    private Points() {
    }

    private static final PoseFactory RED_FACTORY = PoseFactory.degrees();
    private static final PoseFactory BLUE_FACTORY = PoseFactory.degrees()
            .rotateAround(Alliance.FIELD_SIZE / 2, Alliance.FIELD_SIZE / 2, 180);

    /** A current pose, resolved when an auto or TeleOp uses it. */
    public interface PoseSource {
        Pose toPose();
    }

    private static PoseSource blue(Supplier<Point> source) {
        return () -> {
            Point p = source.get();
            return BLUE_FACTORY.of(p.x, p.y, p.headingDeg);
        };
    }

    /** Selects the alliance's CELL in the audience or scoring half of the Pedro field. */
    public static Pose cellTarget(Alliance alliance, double fieldY) {
        return cellTarget(alliance, fieldY < Alliance.FIELD_SIZE / 2);
    }

    /** The alliance's CELL in the audience half (y below the midline) or the scoring half. */
    public static Pose cellTarget(Alliance alliance, boolean audienceHalf) {
        if (alliance == Alliance.BLUE) {
            return (audienceHalf ? Blue.CELL_AUDIENCE : Blue.CELL_SCORING).toPose();
        }
        return (audienceHalf ? Red.CELL_AUDIENCE : Red.CELL_SCORING).toPose();
    }

    /** A field point Panels can edit (unlike Pedro's immutable {@link Pose}). */
    public static final class Point implements PoseSource {
        public double x;
        public double y;
        public double headingDeg;

        public Point(double x, double y, double headingDeg) {
            this.x = x;
            this.y = y;
            this.headingDeg = headingDeg;
        }

        /** The current values as a Pedro pose (heading in radians). */
        public Pose toPose() {
            return RED_FACTORY.of(x, y, headingDeg);
        }
    }

    /** Shared RED alliance points for autonomous routines and TeleOp. */
    @Configurable
    public static final class Red {
        private Red() {
        }

        // ---------- Waypoints ----------
        public static Point START = new Point(56.8937, 9.5709, 90);
        /** RED counterpart of the delayed BLUE parking start. */
        public static Point START_OUTSIDE_END_ZONE = new Point(64.4134, 134.2953, 270);
        /** Starting location for the Least routine. */
        public static Point START_2 = new Point(63.46, 132.8, 90);
        // Shooting headings put the rear-facing turret toward the HIVE.
        public static Point SHOOT_1 = new Point(62.9173, 16.185, 270);
        public static Point FLOWER_PREP_1 = new Point(26.0669, 48.2323, 180);
        public static Point FLOWER_1 = new Point(15.752, 49.0591, 180);
        public static Point SHOOT_2 = new Point(60.2795, 127.3661, 90);
        public static Point FLOWER_PREP_2 = new Point(49.5709, 119.4134, 90);
        public static Point FLOWER_2 = new Point(49.3346, 126.5394, 90);
        public static Point SHOOT_2_RETURN = new Point(61.8937, 127.3268, 90);
        public static Point GARDEN_PREP = new Point(33.0748, 9.2559, 180);
        public static Point GARDEN = new Point(10.9488, 9.7283, 180);
        public static Point SHOOT_1_RETURN = new Point(61.6181, 17.248, 270);
        public static Point STOP_1 = new Point(9.5315, 105.1614, 0);
        /** Parking location inside the RED LOADING ZONE. */
        public static Point STOP_2 = new Point(11, 118.66, 0);

        // Estimated opening centers with the corresponding CELL up. Heading is unused.
        // FIRST manual Fig. 9-10 puts the HIVE centerlines 25.5 inches apart.
        public static Point CELL_AUDIENCE = new Point(58.0, 53.0, 0);
        public static Point CELL_SCORING = new Point(58.0, 88.5, 0);

        // ---------- Bezier control points ----------
        /** start2 → shoot2, from RedCooperateUp.pp.json. */
        public static Point START_2_TO_SHOOT_2_CTRL = new Point(26.7085462999709, 123.37946316254681, 0);
        /** flower1 → shoot2, first control point. */
        public static Point FLOWER_1_TO_SHOOT_2_CTRL_A = new Point(39.1075342942361, 47.42045650357433, 0);
        /** flower1 → shoot2, second control point. */
        // Moved left from (24.05, 117.34) so the robot's corner clears the HIVE by ~5 in.
        public static Point FLOWER_1_TO_SHOOT_2_CTRL_B = new Point(9.0, 117.0, 0);
        /** flower2 → shoot2Return. */
        public static Point FLOWER_2_TO_SHOOT_2_CTRL = new Point(48.23847961425781, 107.75913565499441, 0);
        /** shoot1 → gardenPrep, from RedCooperationDown.pp.json. */
        public static Point SHOOT_1_TO_GARDEN_PREP_CTRL = new Point(55.464719330997355, 24.795270819566625, 0);
        /** shoot2Return → gardenPrep. */
        public static Point SHOOT_2_TO_GARDEN_PREP_CTRL = new Point(25.469588630544294, 125.11931435878847, 0);
        /** shoot1Return → stop1. */
        // Moved down-left from (32.02, 20.87) so the robot clears the HIVE by ~5 in.
        public static Point SHOOT_1_TO_STOP_1_CTRL = new Point(28.0, 12.0, 0);
        /** shoot1 → flowerPrep1: bows the path away from the HIVE corner (~5 in clearance). */
        public static Point SHOOT_1_TO_FLOWER_PREP_1_CTRL = new Point(32.5, 36.0, 0);
    }

    /** Derived BLUE points. Edit Red in Panels; every read uses its latest values. */
    public static final class Blue {
        private Blue() {
        }

        public static final PoseSource START = blue(() -> Red.START);
        public static final PoseSource START_OUTSIDE_END_ZONE = blue(() -> Red.START_OUTSIDE_END_ZONE);
        public static final PoseSource START_2 = blue(() -> Red.START_2);
        public static final PoseSource SHOOT_1 = blue(() -> Red.SHOOT_1);
        public static final PoseSource FLOWER_PREP_1 = blue(() -> Red.FLOWER_PREP_1);
        public static final PoseSource FLOWER_1 = blue(() -> Red.FLOWER_1);
        public static final PoseSource SHOOT_2 = blue(() -> Red.SHOOT_2);
        public static final PoseSource FLOWER_PREP_2 = blue(() -> Red.FLOWER_PREP_2);
        public static final PoseSource FLOWER_2 = blue(() -> Red.FLOWER_2);
        public static final PoseSource SHOOT_2_RETURN = blue(() -> Red.SHOOT_2_RETURN);
        public static final PoseSource GARDEN_PREP = blue(() -> Red.GARDEN_PREP);
        public static final PoseSource GARDEN = blue(() -> Red.GARDEN);
        public static final PoseSource SHOOT_1_RETURN = blue(() -> Red.SHOOT_1_RETURN);
        public static final PoseSource STOP_1 = blue(() -> Red.STOP_1);
        public static final PoseSource STOP_2 = blue(() -> Red.STOP_2);
        public static final PoseSource CELL_AUDIENCE = blue(() -> Red.CELL_SCORING);
        public static final PoseSource CELL_SCORING = blue(() -> Red.CELL_AUDIENCE);
        public static final PoseSource START_2_TO_SHOOT_2_CTRL = blue(() -> Red.START_2_TO_SHOOT_2_CTRL);
        public static final PoseSource FLOWER_1_TO_SHOOT_2_CTRL_A = blue(() -> Red.FLOWER_1_TO_SHOOT_2_CTRL_A);
        public static final PoseSource FLOWER_1_TO_SHOOT_2_CTRL_B = blue(() -> Red.FLOWER_1_TO_SHOOT_2_CTRL_B);
        public static final PoseSource FLOWER_2_TO_SHOOT_2_CTRL = blue(() -> Red.FLOWER_2_TO_SHOOT_2_CTRL);
        public static final PoseSource SHOOT_1_TO_GARDEN_PREP_CTRL = blue(() -> Red.SHOOT_1_TO_GARDEN_PREP_CTRL);
        public static final PoseSource SHOOT_2_TO_GARDEN_PREP_CTRL = blue(() -> Red.SHOOT_2_TO_GARDEN_PREP_CTRL);
        public static final PoseSource SHOOT_1_TO_STOP_1_CTRL = blue(() -> Red.SHOOT_1_TO_STOP_1_CTRL);
        public static final PoseSource SHOOT_1_TO_FLOWER_PREP_1_CTRL = blue(() -> Red.SHOOT_1_TO_FLOWER_PREP_1_CTRL);
    }
}
